import { coerceCssPixelValue } from '@angular/cdk/coercion';
import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
} from '@angular/core';

@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-skeleton',
  template: `
    <div
      class="q-skeleton"
      aria-hidden="true"
      [style.width]="width"
      [style.height]="height"
      [style.border-radius]="radius"></div>
  `,
  styles: [
    `
      .q-skeleton {
        background: var(--ads-color-body-700);
        opacity: 0.05;
        animation: q-skeleton-loading 1.5s ease-in-out infinite;
      }

      @keyframes q-skeleton-loading {
        0% {
          opacity: 0.05;
        }
        50% {
          opacity: 0.03;
        }
        100% {
          opacity: 0.05;
        }
      }
    `,
  ],
})
export class QSkeletonComponent {
  @Input({ transform: coerceCssPixelValue }) width = '100%';
  @Input({ transform: coerceCssPixelValue }) height = 'var(--ads-size-s)';
  @Input({ transform: coerceCssPixelValue }) radius = 'var(--ads-border-radius-xl)';
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-skeleton';
}
